def rearrange_bigger(number: int) -> int:
    """Return the next bigger integer using the same digits, or -1 if none exists."""
    if number < 0:
        raise ValueError("number must be non-negative")

    digits = list(str(number))
    pivot = len(digits) - 2

    while pivot >= 0 and digits[pivot] >= digits[pivot + 1]:
        pivot -= 1

    if pivot < 0:
        return -1

    successor = len(digits) - 1
    while digits[successor] <= digits[pivot]:
        successor -= 1

    digits[pivot], digits[successor] = digits[successor], digits[pivot]
    digits[pivot + 1:] = reversed(digits[pivot + 1:])

    return int("".join(digits))
